use molten::requirement_traceability::*;

fn main() {
    let args = std::env::args().collect::<Vec<_>>();
    if args[1] == "pack" {
        let value = molten::preserves_rail::parse_text(&std::fs::read_to_string(&args[2])
            .expect("actual observed canonical value")).expect("native Preserves parsing");
        std::fs::write(&args[3], molten::preserves_rail::canonical_bytes(&value)
            .expect("native canonical packing")).expect("persist observed packed bytes");
        return;
    }
    let root = std::path::Path::new(&args[1]);
    let spec = std::path::Path::new(&args[2]);
    let output = std::path::Path::new(&args[3]);
    let sources = [SpecSource {
        source: spec.strip_prefix(root).expect("repository-owned governing spec").display().to_string(),
        markdown: std::fs::read_to_string(spec).expect("actual governing requirements"),
        changed: true,
        default_kind: "evidence".into(),
    }];
    let mut requirements = requirements_from_sources(&sources).expect("native requirement extraction");
    requirements.retain(|requirement| requirement.id.starts_with("molten.audit_f14."));
    let expected = [
        "molten.audit_f14.current_binding",
        "molten.audit_f14.duplicate_scope",
        "molten.audit_f14.preserve_state",
        "molten.audit_f14.validation",
    ];
    assert_eq!(requirements.iter().map(|requirement| requirement.id.as_str()).collect::<Vec<_>>(), expected);
    let mut receipts = Vec::new();
    for path in &args[4..] {
        let value = molten::preserves_rail::parse_text(&std::fs::read_to_string(path).expect("saved native receipt"))
            .expect("native verification receipt syntax");
        let receipt = parse_verification_run_receipt(&value).expect("native verification receipt");
        assert!(receipt.diagnostics.is_empty());
        assert_eq!(receipt.decision, if receipt.coverage_kind == "positive" { "pass" } else { "deny" });
        assert_eq!(receipt.exit_status, if receipt.coverage_kind == "positive" { 0 } else { 1 });
        receipts.push(ReceiptCoverageSource { value, target_exists: root.join(&receipt.target).is_file() });
    }
    let coverage = coverage_from_verification_receipts(&receipts).expect("native receipt-backed coverage");
    let manifest = build_traceability_manifest(&TraceabilityInput {
        requirements,
        coverage,
        require_receipt_backed: true,
    }).expect("native F14 receipt-backed manifest");
    assert_eq!(manifest.decision, "pass");
    assert_eq!(manifest.summary.covered.iter().map(String::as_str).collect::<Vec<_>>(), expected);
    assert!(manifest.summary.missing_positive.is_empty());
    assert!(manifest.summary.missing_negative.is_empty());
    assert!(manifest.summary.stale_reference.is_empty());
    assert!(manifest.summary.compatibility_only.is_empty());
    std::fs::write(output, molten::preserves_rail::canonical_bytes(&manifest.value).expect("canonical manifest"))
        .expect("persist actual canonical manifest");
    let readback = build_proof_readback(&manifest).expect("proof readback");
    std::fs::write(output.with_extension("readback.txt"), render_proof_readback(&readback).expect("readback rendering"))
        .expect("save readback");
    println!("traceability ref={} decision={} covered={:?} missing-positive=0 missing-negative=0 stale=0 compatibility-only=0 scope=F14-only",
        manifest.manifest_ref, manifest.decision, manifest.summary.covered);
}
